    let camera: P1CaptureCore_Camera?

    public init(camera: P1CaptureCore_Camera?) {
        self.camera = camera
    }

    public var body: some View {
        ZStack {
            if let frame = liveView.currentFrame {
                Image(nsImage: frame)
