                    .buttonStyle(CaptureOneTheme.Styles.SecondaryButton())

                    Spacer()

                    Button("Reset") {
                        tiltX = 0; tiltY = 0; amount = 0; aspect = 0; skew = 0
                    }
                    .font(.system(size: 10))
                    .foregroundColor(.gray)
                }
                .padding(.top, 4)
            }
        }
