        Button(action: {}) {
            VStack(spacing: 4) {
                Image(systemName: icon)
                    .font(.system(size: 14))
                Text(label)
                    .font(.system(size: 8))
            }
            .frame(width: 50, height: 40)
            .background(Color.white.opacity(0.05))
            .cornerRadius(4)
        }
        .buttonStyle(PlainButtonStyle())
    }
}

