                filtered = filtered.applyingFilter("CIBumpDistortion", parameters: [
                    "inputCenter": CIVector(x: ciImage.extent.midX, y: ciImage.extent.midY),
                    "inputRadius": radius,
                    "inputScale": controller.lensDistortion / 100.0
                ])
            }

