                    "inputIntensity": controller.lensLightFalloff / 100.0,
                    "inputRadius": 1.0
                ])
            }

            let rep = NSCIImageRep(ciImage: filtered)
            let finalImage = NSImage(size: rep.size)
            finalImage.addRepresentation(rep)

            self.renderedImage = finalImage
        }
    }
}

